 static NumericUpDown Number(int min,int max,int value){return new NumericUpDown{Minimum=min,Maximum=max,Value=value,Width=72};}
 static void AddField(Control parent,string label,Control field){parent.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(6,8,0,0)});parent.Controls.Add(field);}
 static void AddButton(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true};b.Click+=delegate{action();};parent.Controls.Add(b);}
 int FrameWidth {get{return output!=null?outW:previewOutput!=null?previewW:(int)width.Value;}}
 int FrameHeight {get{return output!=null?outH:previewOutput!=null?previewH:(int)height.Value;}}
 Placement PlacementNow(){var placement=PlacementCoordinates.FromCenter(x.Value,y.Value,FrameWidth,FrameHeight,(double)scale.Value/100);placement.Loop=videoLoop.Checked;return placement;}
 void ApplyCenter(decimal cx,decimal cy,decimal percent,bool persist){cx=Math.Max(x.Minimum,Math.Min(x.Maximum,cx));cy=Math.Max(y.Minimum,Math.Min(y.Maximum,cy));var placement=PlacementCoordinates.FromCenter(cx,cy,FrameWidth,FrameHeight,(double)percent/100);placement.Loop=videoLoop.Checked;ApplyPlacement(placement,persist);}
 void ApplyPlacement(Placement p,bool persist){var center=PlacementCoordinates.Center(p,FrameWidth,FrameHeight);loading=true;try{videoLoop.Checked=p.Loop;scale.Value=Math.Max(scale.Minimum,Math.Min(scale.Maximum,(decimal)p.Scale*100));x.Value=Math.Max(x.Minimum,Math.Min(x.Maximum,(decimal)center.X));y.Value=Math.Max(y.Minimum,Math.Min(y.Maximum,(decimal)center.Y));}finally{loading=false;}if(selected!=null&&(persist||pointerEditing||settings.Images.ContainsKey(selected)))settings.Images[selected]=PlacementNow();RenderPreview();if(persist)Save();}
 void Scan(){var warnings=new List<string>();catalog=String.IsNullOrEmpty(settings.Root)||!Directory.Exists(settings.Root)?new List<string>():Library.Scan(settings.Root,warnings);RefreshVisible();status.Text=files.Count+" immagini visibili · "+warnings.Count+" cartelle non accessibili";}
 void RenderPreview(){StopSelectionVideo();int w=FrameWidth,h=FrameHeight;try{pending=selectedSource==null?null:Renderer.RenderImage(selectedSource,w,h,PlacementNow());preview.SetFrame(pending==null?null:Renderer.ToBitmap(pending,w,h),w,h);ScheduleSelectionVideo();PublishPreview();status.Text="Anteprima pronta · premi INVIA";}catch(Exception e){pending=null;preview.SetFrame(null,w,h);PublishPreview();status.Text=e.Message;}}
 void UpdateProgram(){if(output==null)return;var sent=output.ReadSentFrame(ref programSequence);if(sent!=null)program.SetFrame(Renderer.ToBitmap(sent,outW,outH),outW,outH);var live=output.ReadOnAirStatus();files.SetOnAir(live);onAirLabel.Text=(output.Error==null?"In onda: ":"Ultimo inviato (ERRORE): ")+(live.Paths.Length==0?"trasparente":String.Join(" + ",Array.ConvertAll(live.Paths,Path.GetFileName)))+(live.Transitioning?" · dissolvenza":"");program.Heading=output.Error==null?"PROGRAMMA · frame inviati":"PROGRAMMA · ERRORE / fermo";program.Footer=output.Error==null?"Monitor locale · non è il ritorno da WATCHOUT":"Ultimo frame inviato · "+output.Error;program.Invalidate();status.Text=output.MediaError??(output.Error==null?"NDI attivo":"ERRORE NDI: "+output.Error);}
 void Toggle(){if(output!=null){escapeGesture.Reset();bool clean=output.StopTransparent();BindCompanion(null);output=null;start.Text="Avvia NDI";SetOutputControlLock();status.Text=clean?"Program arrestato dopo clear trasparente":"Program arrestato: errore durante il clear finale";files.SetOnAir(new OnAirStatus());onAirLabel.Text="In onda: nessuna immagine";configNotice.Text="";program.Heading="PROGRAMMA · NDI arrestato";program.Footer="Nessuna trasmissione";program.SetFrame(null,outW,outH);RefreshPlacementForActiveFormat();status.Text=clean?"Program arrestato dopo clear trasparente":"Program arrestato: errore durante il clear finale";return;}try{programStartError=null;escapeGesture.Reset();string sourceName=NdiChannel.Validate(channelName.Text);if(previewOutput!=null&&String.Equals(sourceName,previewSourceName,StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Il nome Programma coincide con il Preview attivo: arresta Preview prima di rinominare.");channelName.Text=sourceName;settings.ChannelName=sourceName;Save();outW=previewOutput==null?(int)width.Value:previewW;outH=previewOutput==null?(int)height.Value:previewH;activeProgramFps=previewOutput==null?(int)fps.Value:previewFps;if(outW%2!=0)throw new ArgumentException("La larghezza deve essere pari.");programSequence=0;program.Heading="PROGRAMMA · avvio NDI";program.Footer="In attesa del primo frame inviato";program.SetFrame(null,outW,outH);activeProgramSourceName=sourceName;output=new Playout(new NdiSender(sourceName),outW,outH,activeProgramFps);BindCompanion(output);start.Text="Arresta NDI";SetOutputControlLock();RenderPreview();}catch(Exception e){programStartError=e.Message;RefreshOutputIndicators();program.Heading="PROGRAMMA · NDI non avviato";program.Footer=e.Message;program.Invalidate();MessageBox.Show(e.Message,"NDI");}}
 bool Cue(bool clear){if(output==null){status.Text="Avvia prima NDI.";return false;}if(output.Error!=null){status.Text="Invio fermo: arresta e riavvia NDI.";return false;}if(!clear&&pending==null){status.Text="Seleziona un'immagine valida.";return false;}if(!clear&&VideoTools.IsVideo(selected)){try{var initial=Renderer.RenderImage(selectedSource,outW,outH,PlacementNow());var source=new VideoSession(selected,outW,outH,activeProgramFps,PlacementNow(),videoLoop.Checked,initial,ProgramAudio,GainFor(selected),SpeedFor(selected));output.CueSource(source,initial,dissolve.Checked?(double)fade.Value/1000:0,selected);return true;}catch(Exception e){status.Text=e.Message;return false;}}output.Cue(clear?new byte[outW*outH*4]:pending,dissolve.Checked?(double)fade.Value/1000:0,clear?null:selected);return true;}
 void Save(){CaptureProjectControls();UpdateProjectTitle();try{Directory.CreateDirectory(Path.GetDirectoryName(state));string temp=state+".tmp";File.WriteAllText(temp,new JavaScriptSerializer{MaxJsonLength=16*1024*1024}.Serialize(settings));if(File.Exists(state))File.Replace(temp,state,null);else File.Move(temp,state);}catch(Exception e){status.Text="Preferenze non salvate: "+e.Message;}}
